import json
import collections
import sys

def find_path(map_id, start_x, start_y, target_x, target_y, extra_impassable=None, grid_width=None, grid_height=None):
    if extra_impassable is None:
        extra_impassable = []

    # Establish default map bounds and static walls
    impassable = set()
    for obstacle in extra_impassable:
        impassable.add((int(obstacle['x']), int(obstacle['y'])))

    width = 30
    height = 16

    if map_id == "0_146": # Pokémon Tower 5F
        width = 20
        height = 18
        # Define static tombstones and walls for 5F
        for y in range(0, 18):
            impassable.add((0, y))
            impassable.add((19, y))
        for x in range(0, 20):
            impassable.add((x, 0))
            impassable.add((x, 17))
        # Known large solid blocks on 5F:
        for x in range(8, 12):
            for y in range(8, 11):
                impassable.add((x, y))
    elif map_id == "0_147": # Pokémon Tower 6F
        width = 20
        height = 18
        for y in range(0, 18):
            impassable.add((0, y))
            impassable.add((19, y))
        for x in range(0, 20):
            impassable.add((x, 0))
            impassable.add((x, 17))
    elif map_id == "0_208": # Silph Co. 3F
        width = 30
        height = 16
        # Define verified partition walls and tables for Silph Co 3F
        # Row 4 partition wall
        for x in range(21, 29):
            impassable.add((x, 4))
        for x in range(4, 10):
            impassable.add((x, 4))
        # Row 13 partition wall
        for x in range(21, 29):
            impassable.add((x, 13))
        # Column 21 partition wall sections
        for y in [4, 5, 6, 7, 10, 11, 12]:
            impassable.add((21, y))
        # Column 9 partition wall sections
        for y in [4, 5, 6, 7, 10, 11, 12, 13]:
            impassable.add((9, y))
        # Tables and desks
        impassable.update([
            (24, 10), (24, 11), (26, 10), (26, 11),
            (26, 8), (27, 8), (26, 9), (27, 9),
            (12, 8), (13, 8), (12, 9), (13, 9),
            (4, 7), (5, 7), (4, 8), (5, 8), (4, 9), (5, 9), (4, 10), (5, 10)
        ])
        # Outer boundaries
        for y in range(0, 16):
            impassable.add((0, y))
            impassable.add((29, y))
        for x in range(0, 30):
            impassable.add((x, 0))
            impassable.add((x, 15))

    if grid_width is not None:
        width = int(grid_width)
    if grid_height is not None:
        height = int(grid_height)

    # Perform BFS
    start = (int(start_x), int(start_y))
    target = (int(target_x), int(target_y))

    if start == target:
        return []

    queue = collections.deque([[start]])
    visited = {start}

    path_found = None
    while queue:
        path = queue.popleft()
        x, y = path[-1]

        if (x, y) == target:
            path_found = path
            break

        for dx, dy, btn in [(-1, 0, 'Left'), (1, 0, 'Right'), (0, -1, 'Up'), (0, 1, 'Down')]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < width and 0 <= ny < height:
                if (nx, ny) not in impassable and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(path + [(nx, ny)])

    if not path_found:
        return None

    buttons = []
    for i in range(len(path_found) - 1):
        x1, y1 = path_found[i]
        x2, y2 = path_found[i+1]
        if x2 > x1: buttons.append('Right')
        elif x2 < x1: buttons.append('Left')
        elif y2 > y1: buttons.append('Down')
        elif y2 < y1: buttons.append('Up')

    return buttons

if __name__ == "__main__":
    try:
        input_text = sys.stdin.read().strip()
        if not input_text:
            print(json.dumps([]))
            sys.exit(0)
        input_data = json.loads(input_text)

        map_id = input_data.get('map_id')
        start_x = int(input_data.get('start_x'))
        start_y = int(input_data.get('start_y'))
        target_x = int(input_data.get('target_x'))
        target_y = int(input_data.get('target_y'))
        extra_impassable = input_data.get('extra_impassable', [])
        grid_width = input_data.get('grid_width')
        grid_height = input_data.get('grid_height')

        buttons = find_path(map_id, start_x, start_y, target_x, target_y, extra_impassable, grid_width, grid_height)

        if buttons is not None:
            print(json.dumps(buttons))
        else:
            print(json.dumps([]))
    except Exception as e:
        sys.stderr.write(f"Error: {str(e)}\n")
        print(json.dumps([]))
